import * as esbuild from 'esbuild';
import { existsSync, mkdirSync, readFileSync, writeFileSync } from 'fs';
import { dirname } from 'path';

const outfile = '../Sources/PierreDiffsSwift/Resources/pierre-diffs-bundle.js';

// Ensure output directory exists
const outDir = dirname(outfile);
if (!existsSync(outDir)) {
  mkdirSync(outDir, { recursive: true });
}

const isWatch = process.argv.includes('--watch');

/**
 * Builds the highlight worker and writes it into the main bundle's source tree
 * as a string module. The worker cannot be loaded from a URL in the WebView
 * (`loadHTMLString(baseURL: nil)` gives the page a null origin), so the bridge
 * starts it from a blob built out of this string instead.
 */
async function buildWorkerSource() {
  const result = await esbuild.build({
    entryPoints: ['src/worker-entry.js'],
    bundle: true,
    minify: true,
    format: 'iife',
    target: ['safari16'],
    write: false,
    outfile: 'worker.js',
    // @pierre/diffs marks everything but its web components side-effect free,
    // so the worker — which *is* nothing but side effects — is tree-shaken to
    // an empty file unless those annotations are ignored.
    ignoreAnnotations: true,
    define: { 'process.env.NODE_ENV': '"production"' },
  });
  const code = result.outputFiles[0].text;
  mkdirSync('src/generated', { recursive: true });
  writeFileSync(
    'src/generated/worker-source.js',
    '// Generated by bundle.js from src/worker-entry.js — do not edit.\n' +
      `export default ${JSON.stringify(code)};\n`
  );
  console.log(`Worker bundled: ${(code.length / 1024).toFixed(0)} KB`);
}

await buildWorkerSource();

const buildOptions = {
  entryPoints: ['src/diff-entry.js'],
  bundle: true,
  minify: !isWatch,
  sourcemap: isWatch ? 'inline' : false,
  format: 'iife',
  globalName: 'PierreDiffs',
  outfile,
  target: ['safari16'],
  define: {
    'process.env.NODE_ENV': isWatch ? '"development"' : '"production"',
  },
  loader: {
    '.css': 'text',
  },
};

if (isWatch) {
  const context = await esbuild.context(buildOptions);
  await context.watch();
  console.log('Watching for changes...');
} else {
  const result = await esbuild.build(buildOptions);
  const bundle = readFileSync(outfile, 'utf8').replace(/[ \t]+$/gm, '');
  writeFileSync(outfile, bundle);
  console.log('Bundle created successfully!');
  console.log(`Output: ${outfile}`);
  if (result.metafile) {
    console.log(`Size: ${JSON.stringify(result.metafile.outputs, null, 2)}`);
  }
}
